intro=soup.select_one('.intro');intro.clear();intro.append(BeautifulSoup('<div><div class="overline">Ley 31/1995 · Real Decreto 39/1997</div><h1>Prevenir, proteger y participar.</h1><p>El marco preventivo para bomberos: derechos, organización y cifras con sus condiciones.</p></div><span class="badge">Revisión · 10/11/2026</span>','html.parser'))
soup.select_one('.topicstats').clear();soup.select_one('.topicstats').append(BeautifulSoup(f'<span>{len(blocks)} bloques de estudio</span><span>{len(cards)} tarjetas</span><span>{len(quiz)} preguntas explicadas</span><span>BOE · Artículos enlazados</span>','html.parser'))
